"""Intent tests for risk.annualize (M1-T18, RISK-03, TC-06)."""

from __future__ import annotations

import math

import pytest

from risk import Returns, VolSeries, annualize


def _returns(data: dict) -> Returns:
    return Returns(
        base_date=data["base_date"],
        dates=tuple(data["dates"]),
        tickers=tuple(data["tickers"]),
        values={t: tuple(v) for t, v in data["values"].items()},
    )


def _vol(data: dict) -> VolSeries:
    return VolSeries(
        returns=_returns(data["returns"]),
        window=data["window"],
        annualized=data["annualized"],
        values={t: tuple(v) for t, v in data["values"].items()},
    )


def _assert_series(actual: tuple, expected: list, tol: float) -> None:
    assert len(actual) == len(expected)
    for got, want in zip(actual, expected, strict=True):
        if want is None:
            assert got is None
        else:
            assert got == pytest.approx(want, abs=tol)


@pytest.mark.intent
def test_tc06_each_value_scaled_and_gaps_kept(golden):
    data, expected = golden("risk", "TC-06")
    result = annualize(_vol(data["vol"]))
    assert result.annualized is expected["annualized"]
    assert set(result.values) == set(expected["values"])
    for ticker, want in expected["values"].items():
        _assert_series(result.values[ticker], want, expected["tol"])


@pytest.mark.intent
def test_tc06_keeps_returns_and_window(golden):
    data, _ = golden("risk", "TC-06")
    vol = _vol(data["vol"])
    result = annualize(vol)
    assert result.returns == vol.returns
    assert result.window == vol.window


@pytest.mark.intent
def test_periods_per_year_sets_the_scale(golden):
    data, expected = golden("risk", "TC-06")
    vol = _vol(data["vol"])
    result = annualize(vol, periods_per_year=365)
    assert result.annualized is True
    for ticker, daily in vol.values.items():
        want = [None if s is None else s * math.sqrt(365) for s in daily]
        _assert_series(result.values[ticker], want, expected["tol"])


@pytest.mark.intent
def test_annualizing_an_annualized_series_is_value_error(contract_sample):
    vol = _vol(contract_sample("risk.VolSeries"))
    assert vol.annualized is True
    with pytest.raises(ValueError, match="annualized"):
        annualize(vol)


@pytest.mark.intent
def test_annualizing_twice_is_value_error(golden):
    data, _ = golden("risk", "TC-06")
    vol = _vol(data["vol"])
    with pytest.raises(ValueError, match="annualized"):
        annualize(annualize(vol))
"""risk's boundary types: returns, volatility, the summary, the drawdown and the report."""

from collections.abc import Mapping
from dataclasses import dataclass


@dataclass(frozen=True)
class Returns:
    """Daily log returns: `dates` are the prices' dates after the first, which is `base_date`."""

    base_date: str
    dates: tuple[str, ...]
    tickers: tuple[str, ...]
    values: Mapping[str, tuple[float, ...]]


@dataclass(frozen=True)
class VolSeries:
    """Rolling volatility aligned to `returns.dates`; None until `window` earlier returns exist."""

    returns: Returns
    window: int
    annualized: bool
    values: Mapping[str, tuple[float | None, ...]]


@dataclass(frozen=True)
class TickerSummary:
    """One ticker's whole-period statistics."""

    ticker: str
    ann_return: float
    ann_vol: float
    sharpe: float
    last_vol: float | None


@dataclass(frozen=True)
class Drawdown:
    """One ticker's worst fall from a peak; `depth` is at most 0."""

    ticker: str
    depth: float
    peak_date: str


@dataclass(frozen=True)
class Report:
    """The written report: one row per ticker, sorted; the same rows as the file."""

    path: str
    rows: tuple[Mapping[str, object], ...]
"""PL-02 step 3: rolling volatility from earlier returns."""

from statistics import stdev

from risk.types import Returns, VolSeries


def rolling_vol(returns: Returns, window: int) -> VolSeries:
    """Sample stdev of the `window` returns before each date, never its own. ValueError if `window` < 2."""
    if window < 2:
        raise ValueError(f"window must be at least 2, got {window}")
    values = {
        ticker: tuple(
            None if i < window else stdev(series[i - window : i]) for i in range(len(series))
        )
        for ticker, series in returns.values.items()
    }
    return VolSeries(returns=returns, window=window, annualized=False, values=values)

